#!/usr/bin/env bun
// generate-field-profiles.ts: derives the shells' profile data for the Tauri
// workspace (tauri/core/profiles) from manifest.yaml, so the Rust profile
// registry and the manifest cannot drift. The manifest is the source of truth
// for the micro apps and their offline blocks; this script copies id, name,
// brand, roles, devices and the offline block verbatim and never invents a
// scope. One checked in generated file per shell:
//
//   tauri/core/profiles/field.json  complete (apps with their offline blocks)
//   tauri/core/profiles/work.json   declared skeleton (id and name only)
//   tauri/core/profiles/pro.json    declared skeleton (id and name only)
//
// Usage:
//   bun scripts/generate-field-profiles.ts            write the three files
//   bun scripts/generate-field-profiles.ts --check    exit 1 if any differs
//   bun scripts/generate-field-profiles.ts --stdout   print instead of writing
//
// The drift test scripts/field-profiles.test.ts asserts the checked in files
// equal a fresh build; the shell identifier itself is pinned from the Rust
// side (tauri/core/src/profiles.rs reads tauri.conf.json and compares).

import { YAML } from "bun";
import { resolve } from "node:path";

export const REPO_ROOT = resolve(import.meta.dir, "..");
export const MANIFEST_PATH = resolve(REPO_ROOT, "manifest.yaml");
export const PROFILES_DIR = resolve(REPO_ROOT, "tauri/core/profiles");

const SHELLS = ["field", "work", "pro"] as const;
export type ShellName = (typeof SHELLS)[number];

export const PROFILE_FILES: Record<ShellName, string> = {
  field: resolve(PROFILES_DIR, "field.json"),
  work: resolve(PROFILES_DIR, "work.json"),
  pro: resolve(PROFILES_DIR, "pro.json"),
};

interface ManifestOffline {
  mode: string;
  scopes: string[];
  conflict_policy: Record<string, string>;
}

interface ManifestFrontend {
  id: string;
  name: string;
  brand?: string;
  roles?: string[];
  devices?: string[];
  shell: string | string[];
  offline?: ManifestOffline;
}

interface ManifestDoc {
  shape?: number;
  app?: string;
  frontends?: ManifestFrontend[];
}

export interface GeneratedDoc {
  shape: number;
  app: string;
  shell: string;
  brand: string | null;
  source: string;
  apps: Record<string, unknown>[];
}

const SOURCE_NOTE =
  "GENERATED by scripts/generate-field-profiles.ts from manifest.yaml; do not edit by hand. Regenerate with bun scripts/generate-field-profiles.ts, drift check with --check.";

export function shellHolds(frontend: ManifestFrontend, shell: ShellName): boolean {
  const name = `hh-${shell}`;
  return frontend.shell === name || (Array.isArray(frontend.shell) && frontend.shell.includes(name));
}

// One brand across a shell's apps is a profile fact (the plan: the profiles
// differ in brand, hh-pro on Pro). Mixed brands are a manifest change someone
// must look at, not a value to pick silently, so the generator refuses.
export function commonBrand(apps: ManifestFrontend[]): string | null {
  const brands = new Set(apps.map((a) => a.brand ?? null));
  if (brands.size > 1) {
    throw new Error(
      `the shell's apps carry mixed brands (${[...brands].join(", ")}); a profile needs one brand, settle the manifest first`,
    );
  }
  return apps[0]?.brand ?? null;
}

export async function loadManifest(path = MANIFEST_PATH): Promise<ManifestDoc> {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    throw new Error(`manifest not found at ${path}`);
  }
  return YAML.parse(await file.text()) as ManifestDoc;
}

export function buildDoc(manifest: ManifestDoc, shell: ShellName): GeneratedDoc {
  if (manifest.shape !== 1 || manifest.app !== "hh") {
    throw new Error(`manifest does not declare shape 1 of app hh`);
  }
  const frontends = (manifest.frontends ?? []).filter((f) => shellHolds(f, shell));
  const complete = shell === "field";
  const apps = frontends.map((f) => {
    if (complete) {
      if (!f.offline || !Array.isArray(f.offline.scopes)) {
        throw new Error(`${f.id}: the ${shell} shell needs the app's offline block`);
      }
      return {
        id: f.id,
        name: f.name,
        brand: f.brand ?? null,
        roles: f.roles ?? [],
        devices: f.devices ?? [],
        offline: {
          mode: f.offline.mode,
          scopes: f.offline.scopes,
          conflict_policy: f.offline.conflict_policy ?? {},
        },
      };
    }
    // A declared skeleton: what the profile loads, nothing about how (the
    // offline blocks land with each skeleton's own item).
    return { id: f.id, name: f.name };
  });
  return {
    shape: 1,
    app: "hh",
    shell: `hh-${shell}`,
    brand: commonBrand(frontends),
    source: SOURCE_NOTE,
    apps,
  };
}

export function serialize(doc: GeneratedDoc): string {
  return `${JSON.stringify(doc, null, 2)}\n`;
}

async function main(): Promise<void> {
  const argv = process.argv.slice(2);
  const manifest = await loadManifest();
  const docs = SHELLS.map((s) => [s, buildDoc(manifest, s)] as const);
  const texts = docs.map(([s, doc]) => [s, serialize(doc)] as const);

  if (argv.includes("--stdout")) {
    for (const [s, text] of texts) {
      process.stdout.write(`# ${s}.json\n${text}`);
    }
    return;
  }

  if (argv.includes("--check")) {
    let drifted = false;
    for (const [s, text] of texts) {
      const current = await Bun.file(PROFILE_FILES[s]).text().catch(() => "");
      if (current !== text) {
        console.error(`tauri/core/profiles/${s}.json differs from a fresh build of manifest.yaml; run: bun scripts/generate-field-profiles.ts`);
        drifted = true;
      }
    }
    if (drifted) process.exit(1);
    console.log("field, work and pro profiles match the manifest");
    return;
  }

  for (const [s, text] of texts) {
    await Bun.write(PROFILE_FILES[s], text);
    console.log(`wrote tauri/core/profiles/${s}.json`);
  }
}

if (import.meta.main) {
  await main();
}
